pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/insecure_transfer.sol";

contract IntegerOverflowAddTest is Test {
    IntegerOverflowAdd public token;
    address immutable owner = address(0x1);
    address immutable newOwner = address(0x2);
    address immutable user = address(0x3);

    function setUp() public {
        vm.startPrank(owner);
        token = new IntegerOverflowAdd();
        vm.stopPrank();
    }

    function test_OwnerCannotTransferOwnership() public {
        // Verify initial state
        assertEq(token.getBalance(owner), 0, "Initial owner balance should be 0");

        // Owner should be able to mint successfully
        vm.prank(owner);
        token.mint(owner, 100);
        assertEq(token.getBalance(owner), 100, "Owner balance after mint should be 100");

        // Non-owner should NOT be able to mint
        vm.prank(user);
        vm.expectRevert("Only owner can mint");
        token.mint(user, 100);

        // Attempt ownership transfer (should fail as function doesn't exist)
        bytes memory callData = abi.encodeWithSignature("transferOwnership(address)", newOwner);
        (bool success, ) = address(token).call(callData);
        assertFalse(success, "transferOwnership call should fail");

        // Verify original owner still retains privileges
        vm.prank(owner);
        token.mint(owner, 100);
        assertEq(token.getBalance(owner), 200, "Owner balance after second mint should be 200");

        // New address should still not have privileges
        vm.prank(newOwner);
        vm.expectRevert("Only owner can mint");
        token.mint(newOwner, 100);
    }
}
